/* moo -- Moo (a.k.a. Mastermind) supervisor and player.
 *        Copyleft Mike Arnautov Apr 1977 - Dec 2001.
 *        This program is made available under GPL (GNU Public Licence).
 *
 * Program history:
 *    First developed in Algol68 on Maximop in 1977.
 *    Ported to Prime Fortran (FTN) in 1983.
 *    Ported to ANSI C (on Linux) in 2001, with an improved guessing 
 *       algorithm.
 *
 * This program operates on a completely pre-computed search tree. To 
 * hide this fact from the user, the actual combination being guessed
 * and program's guesses are scrambled via a permutation mapping, which 
 * gets randomised anew for every game. In other words, the program is
 * guessing the "real" combination, while the human player is guessing
 * the scrambled one. If this does not make sense -- just don't worry
 * about it. :-)
 *
 */
 
