int eval (char *, char *, char *, int);
int find (char *, char *);
void scramble (char *, char *);          /* Apply the permutation mapping */
char yesnoq (char *, char *);            /* Get a yes, no or quit reply */
void your_move (char *, int);            /* Get player's guess */

/**********************************************************************/

int main()
{
   char history [20];                    /* Dick's guessing history */
   char dhist [500];                     /* Dick's scrambled guesses */
   int i, j, k;                          /* Handy counters */
   long games = 0;                       /* Number of games played */
   int mode;                             /* Who's playing? */
   char input [20];                      /* Input buffer for initial query */
   char guess [5];                       /* Dick's actual guess */
   char board [5];                       /* Actual board combination */
   char display_board [5];               /* Scrambled board */
   char display_guess [5];               /* Dick's scrambled guess */
   char pguess [20];                     /* Player's guess buffer */
   int dres;                             /* Value of Dick's guess */
   int pres;                             /* Value of player's guess */
   int ptot, dtot;                       /* Guess totals across games */
   int pmov, dmov;                       /* Guess totals within games */
   
 /*-------------------------------------------------------------------*/
 
   puts ("[MOO (Mastermind), MLA version Oct 77 - Dec 01]\n");
   if (yesnoq ("Hello, have we met before? [y] ", "y") == 'N')
   {
      puts("\nLet me introduce myself - I am a MOO supervisor.");
      puts("This is Dick, your opponent. Say hallo, Dick.\n");
      sleep (1);
      puts("                    *@_# !!!");
      sleep (1);
      puts("\nEh... he may be a bit simpleminded, but he does play a mean game. The");
      puts("game in question is MOO, also known as MASTERMIND. I think up a four");
      puts("digit code and the player(s) try to guess it. Each guess is evaluated");
      puts("as follows: a bull (B) for a digit correctly placed and a cow (C) for");
      puts("a digit placed incorrectly. Note that you only get one bull OR one");
      puts("cow per digit, e.g. if there is a single 1 in your guess and 1");
      puts("appears twice in the code to be guessed, you only get for it one bull");
      puts("if it is in a correct place or one cow if it is not.");
      puts("\nWhen entering a guess, press the <RETURN > (or <ENTER>) key at the");
      puts("end. Use X instead of your guess to give up on any particular game");
      puts("(this incures the penalty of 15 notional guesses). Q followed by");
      puts("<RETURN> will take you right out of the program at any time.");
   }
   srand (time (NULL));             /* Initialise random number generator */
   while (1)                        /* Work out what the player wants to do */
   {
      puts ("\nDo you wish to:\n");
      puts ("(0) get out of here,");
      puts ("(1) play on your own,");
      puts ("(2) compete against Dick or");
      puts ("(3) see Dick playing\n");
      while (1)
      {
         printf ("Please answer with the appropriate number: ");
         fgets (input, sizeof (input), stdin);
         if (*input == 'q' || *input == 'Q'|| *input == '4' || *input == '0')
         {
            puts ("\nSee you some other time then!\n");
            exit (0);
         }
         if (*input < '1' || *input > '3') continue;
         mode = *input - '0';
         break;
      }
      
 /* Initialisation time! */
 
      games = 0;
      ptot = dtot = 0;
      while (1)            /* Play until the user gets tired of it */
      {
         (void) rand ();   /* Kick the random number generator a few times */
         (void) rand ();
         (void) rand ();
         *board =       rand () % 10 + '0';  /* Randomise the board state */
         *(board + 1) = rand () % 10 + '0';
         *(board + 2) = rand () % 10 + '0';
         *(board + 3) = rand () % 10 + '0';
         *(board + 4) = '\0';
         for (i = 9; i > 1; i--)      /* Construct random scrambling mask */
         {                            /* It is preset as 0,1,2,3... */
            j = rand () % (i + 1);    /* Select one of the remaining digits */
            if (j == i) continue;     /* Swap with the last remaining one */
            k = filter [i]; filter [i] = filter [j]; filter [j] = k;
         }
         scramble (board, display_board);    /* Scranble the board state */
         games++;                            /* Notch up another game */
         printf ("\n Game %d\n\n", games);   /* Announce the new game */
         *history = '\0';                    /* Zap guess history */
         pmov = dmov = 0;                    /* Zap in-game guess totals */
         if (mode > 1) 
            strcpy (guess, "0123");          /* Dick's wired in 1st guess */
/*
 * Print the header, according to the mode: 
 *   1 is player on his own,
 *   2 is player against Dick,
 *   3 is Dick on his own.
 */
         if (mode == 3)
         {
            dres = 0;
            pres = 15;
            printf ("    Dick's\n");
         }
         else if (mode == 2)
         {
            pres = dres = 0;
            printf ("    Dick's           Your\n");
         }
         else
         {
            pres = 0;
            dres = 15;
            printf ("     Your\n");
         }
         printf (" Guess  Score");
         if (mode == 2)
            printf ("    Guess  Score");
         putchar ('\n');
         if (mode == 1)
            printf ("                ");
         else if (mode == 2)
            printf ("                                ");
         else
            putchar ('\n');
/*         
 * If the player is playing, get his initial guess. (If Dick is playing,
 * we already initialised his initial guess.)
 */
         if (mode < 3)
            your_move (pguess, mode);

/* Let us play! Remember that guess value 15 equates to BBBB! */
            
         while (1)
         {
            if (mode < 3)           /* Is the user playing? */
            {
               if (pres == 15)      /* He already guessed it or gave up */
                  putchar ('\n');
               else
               {
                  if (*pguess == 'X' || *pguess == 'x')  /* He's given up */
                  {
                     pres = 15;
                     pmov = 10;
                     if (dres == 15)
                     {
                        printf ("\n The answer was: %s", display_board);
                        if (mode == 3) putchar ('\n');
                     }
                  }
                  else
                  if (*pguess == 'Q' || *pguess == 'q')  /* He wants out! */
                  {
                     puts ("\nWell, goodbye!...\n");
                     exit (0);
                  }
                  else     /* Note user made another guess and evaluate it */
                  {
                     pmov++;
                     pres = eval (display_board, pguess, NULL, 0);
                  }
               }
            }

            if (mode > 1 && dres < 15)    /* Is Dick (still) playing? */
            {
               dres = eval (board, guess, history, dmov); /* Evaluate guess */
               scramble (guess, display_guess);           /* Scramble it */
               strcpy (dhist + 5 * dmov, display_guess);  /* Remember it */
               dmov++;
            }
/*
 * If Dick has made 10 moves, something is wrong -- bomb!
 * Otherwise find in the pre-computed search tree the next guess
 * corresponding to Dick's guessing history so far (we *must* sufcceed!).
 */
            if (dmov == 10 || find (history, guess) != 0) exit (1);
/*
 * If Dick is playing, display his guess (or ****, if the user is (still)
 * playing as well), and theevaluation of the guess.
 */
            if (mode > 1)
            {
               if (dres == 15)
                  printf ("                ");
               else if (pres == 15)
                  printf ("  %s  %s    ", display_guess, score [dres]);
               else
                  printf ("  ****  %s    ", score [dres]);
               if (dres == 14) dres = 15;
            }
/*
 * If the user is (still) playing, show his guess and the evaluation
 * of that guess.
 */
            if (mode < 3 && pres < 15)
            {
               printf ("  %s  %s    ", pguess, score [pres]);
               if (pres < 14) your_move (pguess, mode);
               if (pres == 14) pres = 15;
            }
            if (mode == 3 && dres < 15)            
               putchar ('\n');

/* Is anybody still playing? */

            if (pres >= 15 && dres >= 15)
               break;                        /* No -- end of game */
         }
/*
 * Game is over. Show guess counts and averages. If both players were
 * at it, some of Dick's guess were displayed as ****, so show all
 * his guesses to show there was no cheating.
 */
         dtot += dmov;     /* Update Dick's overall guess count */
         ptot += pmov;     /* Update user's overall guess count */
         puts ("\n");
         if (mode > 1)     /* If Dick was playing, show his guess count */
            printf (" Guesses: %d", dmov);
         if (mode == 2)
             printf ("     ");
          if (mode < 3)    /* If user was playing, show his quess count */
            printf (" Guesses: %d", pmov);
         printf ("\n");
         if (mode > 1)     /* Show Dick's average so far, if appropriate */
            printf (" Average: %0.2f", (float) dtot / games);
         if (mode == 2)
            printf ("  ");
         if (mode < 3)     /* Show user's average so far, if appropriate */
            printf (" Average: %0.2f", (float) ptot / games);
         puts ("\n");
         if (mode == 2)    /* Show Dick's guesses, if necessary */
         {
            printf (" Dick's guesses were:");
            for (i = 0; i < dmov; i++)
               printf (" %s", dhist + 5 * i);
            puts ("\n");
         }
         if (yesnoq ("Another game? [y] ", "y") == 'N')
            break;
      }
   }
}

/**********************************************************************/
/* 
 * Evaluate a guess.
 */
  
int eval (char *target, char *guess, char *history, int depth)
{
   int bulls, cows;  /* Counts of bulls and cows */
   int i, j;         /* Loop counters */
   int result;       /* Result to return */
   int  u[4], v[4];  /* Guess and target digit availability masks */
   char display_guess [5];

/*--------------------------------------------------------------------*/

   for (i = 0; i < 4; ++i) 
   {
      u[i] = 1;      /* Digits of guess not accounted for yet */
      v[i] = 1;      /* Digits of target ditto */
   }
   bulls = 0;                      /* No bulls seen yet */
   for (i = 0; i < 4; ++i)         /* Count the number of bulls */
   {
      if (guess[i] == target[i])   /* Is it a bull? */
      {
         bulls++;                  /* Note we had one */
         u[i] = 0;                 /* This guess digit accounted for */
         v[i] = 0;                 /* This target digit ditto */
      }
   }
   cows = 0;                       /* No cows seen yet */
   for (i = 0; i < 4; ++i)         /* For each digit of the guess... */
   {
      if (u[i])                    /* Is this digit still available? */
         for (j = 0; j < 4; ++j)   /* Loop through target digits */
         {
            if (v[j])              /* But only look at the available ones */
            if (guess[i] == target[j])    /* Is it a cow? */
            {
               cows++;             /* Notch up a cow */
               u[i] = 0;           /* Take this guess digit out of scoring */
               v[j] = 0;           /* And ditto for the target digit */
               break;              /* Clearly done with this guess digit! */
            }
         }
   }
/* 
 * We want to return consecutive numbers from 0 to 14. The below formula 
 * magically does exactly what we want.
 */
   result = (bulls * (11 - bulls)) / 2 + cows;
/*
 * Subsequent guesses depend on guess history so far, so keep track
 * of that history!
 */
   if (history)
   {
      *(history + depth) = 'A' + result;
      *(history + depth + 1) = '\0';
   }
/*
 * Don't forget to translate the guess into what the user shuold see!
 */
   scramble (guess, display_guess);
   return (result);
}

/**********************************************************************/
/*
 * Find the next guess in the pre-computed search tree. The tree stores
 * all possible search histories, stored as a sequence of guess outcomes
 * (values 0 to 15 used as offsets from the letter 'A'), followed by the
 * first digit of the guess to make (which conveniently marks the end
 * of the history sequence), followed by the remaining three digits,
 * stored ni base36 notation (0-9,A-Z).
 */
 
int find (char *history, char *guess)
{
   int bot, mid, top;      /* Bottom, middle and top for binary chop */
   int second, third;      /* 2nd & 3d base36 digits of next guess */
   int result;             /* Result to return */
   char *p1, *p2;          /* Pointers into history strings */

/*--------------------------------------------------------------------*/

   bot = 0;                                /* Binary search absolute bottom */
   top = sizeof (moo) / sizeof (moo [0]);  /* And the absolute top */

   while (bot < top)                       /* Chop, chop!... */
   {
      mid = (top + bot) / 2;               /* Current mid-point */
      p1 = history;
      p2 = moo [mid];
      while (*p1 == *p2)                   /* Compare against actual history */
      {
         p1++; 
         p2++;
      }
      if (*p1 == '\0')                     /* End of actual history? */
      {
         if (*p2 < 'A') break;             /* End of this history entry? */
         top = mid;                        /* OK -- found it! */
      }
      else if (*p1 < *p2)                  /* We are too high, so ... */
         top = mid;                        /* ... lower the top */
      else
      {
         bot = mid;                        /* Must be too low, so ... */
         if (top == bot + 1) break;        /* ... raise the bottom */
      }
   }
   
/* Check for the impossible error conditions -- just in case! */

   if (strncmp (moo [mid], history, strlen (history))) return (0);
   if ((*guess = *(moo [mid] + strlen (history))) > '9') return (0);
/*
 * We've just put the 1st guess digit into *guess -- now decode
 * the remaining three.
 */
   second = *(moo [mid] + strlen (history) + 1); /* Second char is encoded */
   if (second > '9') second -= 'A' - '9' - 1;    /* Eliminate '9' to 'A' gap */
   third = *(moo [mid] + strlen (history) + 2);  /* Third char is encoded */
   if (third > '9') third -= 'A' - '9' - 1;      /* Again, eliminate the gap */
   result = 36 * (second - '0') + third - '0';   /* Work out the value */

/* Now express same value in decimal */

   *(guess + 3) = result % 10 + '0';         /* Last (fourth) digit */
   result /= 10;                             
   *(guess + 2) = result % 10 + '0';         /* Third digit */
   *(guess +1) = result / 10 + '0';          /* Second digit */

   return (0);
}

/**********************************************************************/
/*
 * Scranble a four digit string by running it through the permutation
 * "filter".
 */

void scramble (char *instring, char *outstring)
{
   int digit;

/*--------------------------------------------------------------------*/

   while (*instring)
   {
      digit = *instring++ - '0';
      *outstring++ = *(filter + digit);
   }
   *outstring = '\0';
}

/**********************************************************************/
/*
 * Ask a question and get a yes/no/quit answer.
 */
 
char yesnoq (char *prompt, char *dflt)
{
   char reply [20];

/*--------------------------------------------------------------------*/

   while (1)
   {
      printf (prompt);
      if (fgets (reply, sizeof (reply), stdin) == NULL) exit (0);
      if (*reply == '\n') *reply = *dflt;
      if (*reply >= 'a' && *reply <= 'z') *reply -= 'a' - 'A';
      if (*reply == 'Q') 
      {
         puts ("\nAs you wish...\n");
         exit (0);
      }
      if (*reply == 'Y' || *reply == 'N') return (*reply);
      puts ("Please answer Yes, No or Quit!\n");
   }
}

/**********************************************************************/
/*
 * Get player's move, and check its validity.
 */
 
void your_move (char *pguess, int mode)
{
   int error = 0; /* Counts possible outstanding errors */
   char *ptr;     /* Pointer into player's guess */

/*--------------------------------------------------------------------*/

   while (1)   
   {
      ptr = pguess;
      if (error)
      {
         printf (mode == 1 ? "                " : 
                             "                                ");
         printf ("Must be 4 digits! Try again: ");
      }
      else
         printf ("Enter your guess: ");
      error = 5;                    /* Maximum error count */
      fgets (ptr, 20, stdin);
      *(ptr + 19) = '\0';
      if (*ptr == 'q' || *ptr == 'Q' || *ptr == 'x' || *ptr == 'X')
         return;
      *(ptr + strlen (ptr) - 1) = '\0'; /* Make sure it is terminated! */
      if (strlen (ptr) == 4)
      {
         error--;                   /* The length is correct, at least */
         while (*ptr)               
            if (isdigit (*ptr++))   /* Each one must be a digit */
               error--;
      }            
      if (error == 0)   /* Any possible errors unaccounted for? */
         return;
   }
}

